def head(n,title):
 if story:story.append(PageBreak())
 add(f'{n:02d} / APPLICATION DOCUMENTATION','SmallD');add(title,'HeadD')
def sec(t):add(t,'SectionD')
def bullets(items):
 for t in items:add('• '+t)
def table(rows,widths=None):
 data=[[p(str(x),'SmallD' if i else 'BodyD') for x in r] for i,r in enumerate(rows)]
 t=Table(data,colWidths=widths or [155,340],hAlign='LEFT',repeatRows=1)
