add('Scenes and procedural sound are application-authored. No downloaded stock music or custom voice recordings are required. The repository currently has no project-level LICENSE file. Third-party licences do not assign a licence to Drishya source.','SmallD')
sec('Source links');add('<link href="https://huggingface.co/Qwen/Qwen3-8B">Qwen3-8B model card</link> · <link href="https://huggingface.co/ai4bharat/indic-parler-tts">Indic Parler model card</link><br/><link href="https://www.remotion.dev/docs/license">Remotion licence</link> · <link href="https://ffmpeg.org/legal.html">FFmpeg licensing</link><br/>Repository references: README.md, docs/V2-ARCHITECTURE.md, docs/PYTHON-LOOP-VISUALS.md and services/inference/README.md.','SmallD')
