 w,h=A4;c.saveState();c.setFillColor(cream);c.rect(0,h-24,w,24,fill=1,stroke=0);c.setFillColor(pink);c.rect(42,h-24,65,5,fill=1,stroke=0);c.setStrokeColor(line);c.line(48,41,w-48,41);c.setFont('Helvetica',8);c.setFillColor(muted);c.drawString(48,27,'DRISHYA / APP DOCUMENTATION');c.drawRightString(w-48,27,f'{doc.page}');c.restoreState()
